"                if (res.ok) {
                    // Save to localStorage for dynamic telemetry tracking
                    try {
                        localStorage.setItem('rivenquant_config_code_' + activeAsset, JSON.stringify({
                            params: params,
                            code_length: editor.value.length
                        }));
                    } catch (e) {
                        console.error("Error saving strategy params:", e);
                    }

                    statusEl.className = "text-xs font-mono mr-auto self-center text-emerald-400";
                    statusEl.innerText = "Успешно сохранено и скомпилировано!";
                    showActionToast("Стратегия сохранена!");
                    if (currentProductMode === 'lite' && quickStartMode === 'custom') {
                        advanceWorkflowStep(activeAsset, 'custom', 'strategy_save');
                    }
                    setTimeout(() => closeStrategyCodingModal(), 1000);"

